// Runtime oracle is generated by orbit-parity.py from immutable production C + LVGL.
use super::*;

#[test]
fn orbit_scaled_preview_uses_linear_sampling_on_create_and_update() {
    for side in 0..2 {
        let ctx = egui::Context::default();
        for time in [0.0, 0.05] {
            let mut texture_id = None;
            let output = ctx.run_pass(egui::RawInput { time: Some(time), ..Default::default() }, |ctx| {
                ctx.root_ui(|ui| egui::CentralPanel::default().show(ui, |ui| {
                    texture_id = sm62_orbit_update(ui, side, true, true, false).map(|t| t.id());
                }));
            });
            let options: Vec<_> = output.textures_delta.set.iter()
                .filter(|(id, _)| Some(*id) == texture_id.as_ref())
                .flat_map(|(_, deltas)| deltas.iter().map(|d| d.options))
                .collect();
            output.drop_without_applying_deltas();
            assert!(!options.is_empty(), "production Orbit texture must be uploaded");
            assert!(options.iter().all(|o| o.magnification == egui::TextureFilter::Linear
                && o.minification == egui::TextureFilter::Linear),
                "scaled Entropy preview must smooth both enlargement and reduction: {options:?}");
        }
    }
}

#[test]
#[ignore = "requires ORBIT_PARITY_DIR from the production C renderer"]
fn orbit_production_c_timeline_pixel_parity_both_halves() {
    let directory = std::path::PathBuf::from(std::env::var_os("ORBIT_PARITY_DIR").expect("C renderer evidence"));
    for side in 0..2 {
        let ctx=egui::Context::default();
        let mut textures=std::collections::HashMap::new();
        let timeline:Vec<serde_json::Value>=std::fs::read_to_string(directory.join("c-reference-timeline.log")).unwrap().lines()
            .filter(|line|line.starts_with('{')).map(|line|serde_json::from_str(line).unwrap()).collect();
        for sample in 0..timeline.len() {
            // Drive the same temporary-keymap / screens-off boundaries as C.
            if [183,187,191].contains(&sample) {
                let (time,off)=match sample {183=>(10.001,false),187=>(12.501,false),_=>(14.001,true)};
                let inactive=ctx.run_pass(egui::RawInput {time:Some(time),..Default::default()},|ctx| {
                    ctx.root_ui(|ui|egui::CentralPanel::default().show(ui,|ui| {
                        paint_sm62_screen(ui,egui::Rect::from_min_size(egui::Pos2::ZERO,egui::vec2(240.0,280.0)),
                            &[2,1,20,1,1],2,false,side,None,false,off,false);
                    }));
                });inactive.drop_without_applying_deltas();
            }
            let time=timeline[sample]["time_ms"].as_u64().unwrap() as f64/1000.0;
            let idle=(187..=192).contains(&sample);
            let out=ctx.run_pass(egui::RawInput { time:Some(time),
                screen_rect:Some(egui::Rect::from_min_size(egui::Pos2::ZERO,egui::vec2(400.0,400.0))),..Default::default() },|ctx| {
                ctx.root_ui(|ui|egui::CentralPanel::default().show(ui,|ui| {
                    paint_sm62_screen(ui,egui::Rect::from_min_size(egui::Pos2::ZERO,egui::vec2(240.0,280.0)),
                        &[if idle {0} else {2},1,20,1,1],if idle {1} else {0},false,side,None,false,false,false);
                }));
            });
            for (id,deltas) in &out.textures_delta.set { for delta in deltas {
                let egui::ImageData::Color(image)=&delta.image;
                if let Some([x,y])=delta.pos {
                    let previous: &mut egui::ColorImage=textures.get_mut(id).expect("existing texture");
                    for row in 0..image.height() {
                        previous.pixels[(y+row)*previous.size[0]+x..(y+row)*previous.size[0]+x+image.width()]
                            .copy_from_slice(&image.pixels[row*image.width()..(row+1)*image.width()]);
                    }
                } else { textures.insert(*id,(**image).clone()); }
            }}
            let shape=out.shapes.iter().find_map(|s|match &s.shape {
                egui::Shape::Rect(r) if r.brush.is_some()=>Some(r),_=>None
            }).expect("actual production painter texture");
            let brush=shape.brush.as_ref().unwrap(); let image=&textures[&brush.fill_texture_id];
            let mut actual=Vec::new();
            for y in 0..280 {for x in 0..240 {
                let u=brush.uv.min.x+(x as f32+0.5)/240.0*brush.uv.width();
                let v=brush.uv.min.y+(y as f32+0.5)/280.0*brush.uv.height();
                actual.extend_from_slice(&image.pixels[(v*image.height() as f32) as usize*image.width()+(u*image.width() as f32) as usize].to_array());
            }}
            let expected=std::fs::read(directory.join(format!("frame-{sample:03}.rgba"))).unwrap();
            // Compare only pixels covered by the production painter's rounded
            // physical-panel mask. LVGL's generic 6px view corners are outside
            // that 3mm mask; their black backing is not part of Orbit content.
            let radius=f32::from(shape.corner_radius.nw);
            let covered=|index:usize| {
                let x=(index%240) as f32+0.5;let y=(index/240) as f32+0.5;
                let dx=(radius-x).max(x-(240.0-radius)).max(0.0);
                let dy=(radius-y).max(y-(280.0-radius)).max(0.0);
                dx*dx+dy*dy<=radius*radius
            };
            let different=actual.chunks_exact(4).zip(expected.chunks_exact(4)).enumerate().filter(|(i,(a,b))|covered(*i)&&a!=b).count();
            if different!=0 {std::fs::write(directory.join(format!("rust-side-{side}-sample-{sample}.rgba")),&actual).unwrap();}
            out.drop_without_applying_deltas();
            assert_eq!(different,0,"production Orbit C/Rust mismatch side={side} sample={sample} (arrival, stars, ship/flame, cadence, wrap)");
        }
    }
}
